import{_ as e,c as r,o as t,ae as o}from"./chunks/framework.gg_j4Wdb.js";const u=JSON.parse('{"title":"Clase CartaPorte","description":"","frontmatter":{},"headers":[],"relativePath":"docs/v3.0/carta-porte/clase-cartaporte.md","filePath":"docs/v3.0/carta-porte/clase-cartaporte.md"}'),s={name:"docs/v3.0/carta-porte/clase-cartaporte.md"};function c(n,a,p,i,l,d){return t(),r("div",null,a[0]||(a[0]=[o('<h1 id="clase-cartaporte" tabindex="-1">Clase CartaPorte <a class="header-anchor" href="#clase-cartaporte" aria-label="Permalink to &quot;Clase CartaPorte&quot;">​</a></h1><p>La biblioteca incluye soporte para generar el complemento Carta Porte versión 3.1, requerido por el SAT para amparar el traslado de bienes o mercancías en territorio nacional.</p><p>Para construir este complemento, el paquete proporciona clases específicas por medio de transporte, permitiendo una estructura clara, modular y compatible con los requisitos fiscales actuales.</p><p>Ya sea que transportes vía terrestre, marítima, aérea o ferroviaria, puedes usar estas clases para generar nodos válidos que pueden integrarse fácilmente dentro del CFDI como parte del complemento.</p><p>En las siguientes secciones se documentan los métodos comunes que aplican a todos los medios de transporte, independientemente de si el traslado es terrestre, marítimo, aéreo o ferroviario. Estos métodos permiten construir la estructura base del complemento Carta Porte, como las ubicaciones, mercancías, figuras del transporte, entre otros.</p><p>Puede ir rapidamente a cualquier tipo de medio de transporte dando click en los siguientes enlaces:</p><ul><li><a href="/cfdi-sat-nodejs/docs/v3.0/carta-porte-autotransporte/clase-CartaPorteAutotransporte.html">CartaPorte para Autotransportes</a></li><li><a href="/cfdi-sat-nodejs/docs/v3.0/carta-porte-autotransporte/clase-CartaPorteAutotransporte.html">CartaPorte para transportes marítimos</a></li><li><a href="/cfdi-sat-nodejs/docs/v3.0/carta-porte-autotransporte/clase-CartaPorteAutotransporte.html">CartaPorte para transportes aéreos</a></li><li><a href="/cfdi-sat-nodejs/docs/v3.0/carta-porte-autotransporte/clase-CartaPorteAutotransporte.html">CartaPorte para transportes ferroviarios</a></li></ul>',7)]))}const f=e(s,[["render",c]]);export{u as __pageData,f as default};
